#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: switch on the Value Board's Claude connector (/mcp), ADR 0004 and docs/setup.md section 6.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
BOARD="https://hbf-value-board.sunridge.app"
RESOURCE="$BOARD/mcp"

banner "Value Board: Claude connector"

stage "Check the go-ahead"
say "The connector lets Sunridge Members read and change the board from Claude as themselves."
say "It sends board content to Claude, so spec question Q1 (Partners and Sunridge IT) must be answered first."
confirm "Has Q1 been answered yes for the Value Board?" || { SKIPPED+=("answer spec question Q1, then run this again"); finish; exit 0; }

stage "Entra: register the board"
open_url "https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade"
step "New registration → Name: Sunridge Value Board → Accounts in this organizational directory only → Register."
step "On its Overview page, copy the Directory (tenant) ID and the Application (client) ID."
ask ENTRA_TENANT_ID "Paste the Directory (tenant) ID:"
ask ENTRA_CLIENT_ID "Paste the Application (client) ID of Sunridge Value Board:"

stage "Entra: the board's address and scope"
step "In Sunridge Value Board → Expose an API → Application ID URI → Add → set it to:"
say "    $RESOURCE"
step "Add a scope → name Board.ReadWrite → Admins and users → display name 'Use the Value Board as you' → Add scope."
step "Manifest → set \"requestedAccessTokenVersion\" to 2 (under \"api\") → Save. The board accepts v2 tokens only."
pause

stage "Entra: an app for Claude"
step "Back to App registrations → New registration → Name: Claude connector (Value Board) → this directory only."
step "Redirect URI: Web → the callback address Claude shows when you add a custom connector."
note "At the time of writing it is https://claude.ai/api/mcp/auth_callback; use the one Claude shows if it differs."
step "Certificates & secrets → New client secret → copy the Value now (it is shown once). Keep it for stage 8; don't save it in a file."
step "API permissions → Add a permission → My APIs → Sunridge Value Board → Delegated → Board.ReadWrite → Add."
step "Grant admin consent for Sunridge."
ask CLAUDE_APP_CLIENT_ID "Paste the Application (client) ID of Claude connector:"

stage "Cloudflare: let Claude reach /mcp"
say "Claude signs in with Microsoft tokens, which the board checks itself. It can't pass Cloudflare's login,"
say "so Access must let these two paths through, and only these two:"
say "    hbf-value-board.sunridge.app/mcp"
say "    hbf-value-board.sunridge.app/.well-known/oauth-protected-resource/mcp"
open_url "https://one.dash.cloudflare.com/"
step "Zero Trust → Access → Applications → Add an application → Self-hosted → Name: Value Board – Claude endpoint."
step "Add both paths above as public hostnames (domain hbf-value-board.sunridge.app, with each path)."
step "Policy: Action Bypass, Include Everyone. Save."
confirm "Bypass saved for exactly those two paths (nothing wider)?" || { SKIPPED+=("Cloudflare Access bypass for /mcp and its metadata path"); }

stage "Render: switch it on"
open_url "https://dashboard.render.com/"
step "sunridge-value-board → Environment → set these three, then Save, rebuild and deploy:"
say "    CLAUDE_ACCESS_ENABLED=true"
say "    ENTRA_TENANT_ID=$ENTRA_TENANT_ID"
say "    ENTRA_CLIENT_ID=$ENTRA_CLIENT_ID"
confirm "Saved and deploying?" || SKIPPED+=("Render environment: CLAUDE_ACCESS_ENABLED, ENTRA_TENANT_ID, ENTRA_CLIENT_ID")

stage "Check the endpoint answers"
say "Once the deploy is live, the board should describe itself to Claude without a Cloudflare login."
pause
if command -v curl >/dev/null 2>&1; then
  body=$(curl -s --max-time 15 "$BOARD/.well-known/oauth-protected-resource/mcp" || true)
  if [[ "$body" == *"$RESOURCE"* ]]; then step "${GREEN}OK${RESET}: the metadata names $RESOURCE."
  else warn "Unexpected answer; check the deploy and the Cloudflare bypass:"; note "${body:0:300}"; SKIPPED+=("metadata check at $BOARD/.well-known/oauth-protected-resource/mcp"); fi
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 -X POST "$RESOURCE" || true)
  [[ "$code" == "401" ]] && step "${GREEN}OK${RESET}: /mcp asks for a Microsoft token (401)." || { warn "/mcp answered $code (expected 401)."; SKIPPED+=("/mcp should answer 401 without a token"); }
else
  SKIPPED+=("check $BOARD/.well-known/oauth-protected-resource/mcp by hand (curl not found)")
fi
pause

stage "Claude: add the connector"
open_url "https://claude.ai/settings/connectors"
step "Add custom connector → Name: Sunridge Value Board → URL: $RESOURCE"
step "Advanced settings → OAuth Client ID: $CLAUDE_APP_CLIENT_ID → OAuth Client Secret: the secret from stage 4 → Add."
step "Connect → sign in with your Sunridge Microsoft account → accept."
step "Test in a new chat: \"List the Projects at HBF on the Value Board.\""
note "To give every Sunridge Member the connector, an organisation owner adds it under Organization settings → Connectors."
pause

finish
